<template>
  <div :id="col.name + '_' + rowKey + '_parent'">
    <q-input
      outlined
      :disable="
        isReadOnly ||
        (lineItemLayout[col.name] && lineItemLayout[col.name].is_readonly) ||
        isColumnReadOnly(col.name)
      "
      :class="
        'input-text-28px ' +
        (col.name + '_' + rowKey) +
        ' input_column_type ' +
        col?.column_type?.toLowerCase()
      "
      @change="inputValueChanges(col.name, rowKey)"
      @keydown.tab.prevent="handleTabKey($event, col.name, rowKey)"
      v-model="modelVaule"
      :data-column-name="col.name"
    >
      <template v-slot:prepend>
        <q-icon
          v-if="lineItemsErrorsRaw?.[rowKey]?.[col.name.toLowerCase()]"
          name="priority_high"
          class="headerError"
          color="red"
        >
          <q-tooltip class="bg-red line-error-tooltip">
            {{ lineItemsErrorsRaw[rowKey][col.name.toLowerCase()] }}
          </q-tooltip>
        </q-icon>
        <template
          v-if="
            table_lookup_loading_fields[col.name] &&
            table_lookup_loading_fields[col.name][rowKey]
          "
        >
          <div
            v-if="table_lookup_loading_fields[col.name][rowKey].lookup_loading"
          >
            <q-spinner-ios color="primary" size="0.86em" />
          </div>

          <q-icon
            v-if="
              table_lookup_loading_fields[col.name][rowKey].lookup_found == true
            "
            flat
            dense
            name="check_circle"
            size="18px"
            class="cursor-pointer text-light-green-8"
            tabindex="0"
          >
            <q-tooltip>{{ $t('lookup_record_found') }}</q-tooltip>
          </q-icon>

          <q-icon
            v-if="
              table_lookup_loading_fields[col.name][rowKey].lookup_found ==
              false
            "
            flat
            dense
            name="warning"
            size="18px"
            class="cursor-pointer text-orange"
            tabindex="0"
          >
            <q-tooltip>{{ $t('no_lookup_record_found_for_list') }}</q-tooltip>
          </q-icon>
        </template>
      </template>
    </q-input>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { Acl, FieldPermission } from 'src/core/acls/Acl';
import amountConversionHelper from 'src/utils/amountConversionHelper';
import {
  useDocumentStore,
  useLineItemStore,
  useAmountFormatStore,
  useDocMasterDataLookUpStore,
  useLookupFunctionStore,
} from 'src/store/main';

export default defineComponent({
  name: 'TableInputField',
  props: {
    col: {
      type: Object,
      required: true,
    },
    rowKey: {
      type: String,
      required: true,
    },
    lineItemLayout: {
      type: Object,
      required: true,
    },
    lineItemsErrorsRaw: {
      type: Object,
      required: true,
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  mixins: [amountConversionHelper],
  emits: ['inputValueChanges'],
  computed: {
    cellValue(): any {
      return this.lineDataObj[this.rowKey]?.columns?.[this.col.name]
        ?.formatted_value;
    },
  },
  watch: {
    cellValue(newVal, oldVal) {
      if (this.isUserTyping) {
        // Skip watcher logic if user is typing
        return;
      }
      this.initModelVaule();
      this.inputValueChanges(this.col.name, this.rowKey);
    },
  },
  data() {
    return {
      modelVaule: '' as number | string,
      attributeKey: 'column_name',
      isUserTyping: false,
    };
  },
  mounted() {
    this.initModelVaule();
  },
  methods: {
    /**
     * Check if a column should be read-only based on ACL permissions
     * Column is read-only if permission is exactly READ_ONLY
     * Uses table_column_access from ACL
     */
    isColumnReadOnly(columnName: string): boolean {
      const colId = this.lineItemLayout ? this.lineItemLayout[columnName]?.id : null;
      if (!colId) {
        return false;
      }
      return Acl.isColumnPermission(this.record?.doc_type, colId, FieldPermission.READ_ONLY);
    },

    initModelVaule() {
      this.modelVaule =
        this.lineDataObj[this.rowKey]['columns'][this.col.name].formatted_value;
    },
    inputValueChanges(column_name: string, rowId: string) {
      this.isUserTyping = true;
      this.lineDataObj[this.rowKey]['columns'][this.col.name].formatted_value =
        this.modelVaule;
      // Call the table-specific value changes method
      this.$emit('inputValueChanges', column_name, rowId);

      const autoTriggerObject = this.autoTriggerTableFields[column_name];

      if (autoTriggerObject) {
        const currectDataSet = this.preapreAutoTriggerList(
          autoTriggerObject,
          column_name,
        );
        this.processTableAutoTriggerFields(currectDataSet);
      }

      // Reset flag after input is processed
      this.$nextTick(() => {
        this.isUserTyping = false;
      });
    },
    handleTabKey(event: any, colName: string, key: any) {
      const allInputs = Array.from(document.querySelectorAll('input'));
      const currentIndex = allInputs.indexOf(event.target);
      if (currentIndex !== -1 && currentIndex < allInputs.length - 1) {
        const nextInput = allInputs[currentIndex + 1];
        nextInput.focus();
      }
    },

    async processTableAutoTriggerFields(currectDataSet: any) {
      if (!currectDataSet || currectDataSet.length == 0) {
        return;
      }

      currectDataSet = this.removeDuplicateGroups(currectDataSet);

      let lookupsList = [];

      for (let item of currectDataSet) {
        if (item.triggerDataSet) {
          lookupsList.push(item);
        }

        const lookups = this.findDependentLookups(
          this.record.tables[0].lookup_configurations,
          item.lookup_dataset_name,
          item.fieldName,
        );

        if (lookups && lookups.length > 0) {
          lookupsList.push(...lookups);
        }
      }

      lookupsList = this.removeDuplicateGroups(lookupsList);

      for (let item of lookupsList) {
        const configFields =
          this.lookupTableDictionary[item.id]['fields'];

        if (!this.lineDataObj[this.rowKey]['columns'][item.fieldName]) {
          continue;
        }
        this.setLookupFieldStatus(
          configFields,
          true,
          configFields.lookup_dataset_name,
          null,
        );

        item.rowId = this.rowKey;
        const response = await this.loadAutoTriggerData(
          item,
          this.lineDataObj[this.rowKey]['columns'][item.fieldName]
            .formatted_value,
          true,
        );
        if (response && response.message == 'not_executed') {
          this.setLookupFieldStatus(
            configFields,
            false,
            item.lookup_dataset_name,
            false,
          );
          continue;
        }

        if (!response || !response.data || response.data.length == 0) {
          this.resetChildFields(
            this.lookupTableDictionary[item.id],
            item.fieldName,
          );
          this.setLookupFieldStatus(
            configFields,
            false,
            item.lookup_dataset_name,
            false,
          );
          continue;
        }

        this.populateMasterDataFields(
          this.lookupTableDictionary[item.id],
          item.fieldName,
          JSON.stringify(response.data[0]),
        );
        this.setLookupFieldStatus(
          configFields,
          false,
          item.lookup_dataset_name,
          true,
        );
      }
    },

    async populateMasterDataFields(
      config: dynamicObj,
      autoTriggedField: string,
      master_data_row: string,
    ) {
      this.table_lookup_loading_fields = {};
      try {
        // this.closeMsDialog();
        const conversionFields = this.getConversionFields();
        // General Response-Data for all the respective Fields
        let jsonResponse = JSON.parse(master_data_row);
        const values = [];
        const lookup_fields = config.fields;
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field[this.attributeKey];
          const lookup_field = field.lookup_field.toLowerCase();
          if (
            jsonResponse.hasOwnProperty(lookup_field) &&
            conversionFields.includes(field_name) &&
            jsonResponse[lookup_field] != null
          ) {
            values.push({
              key: jsonResponse[lookup_field],
              value: jsonResponse[lookup_field],
            });
          }
        }
        let formatted_values = [] as dynamicObj[];
        if (values.length > 0) {
          formatted_values = await this.formatMultiValues(
            values,
            'en_US',
            this.amount_format_locale,
          );
        }

        const extraction_method = 'MD';
        for (let [index, field] of lookup_fields.entries()) {
          const field_name = field[this.attributeKey];
          const lookup_field = field.lookup_field.toLowerCase();
          if (
            !this.lineDataObj[this.rowKey]['columns'].hasOwnProperty(
              field_name,
            ) ||
            autoTriggedField == field_name
          ) {
            //as autoTriggedField is already up to date so do not update that field
            continue;
          }

          if (jsonResponse.hasOwnProperty(lookup_field) == false) {
            continue;
          }

          let formatted_value = jsonResponse[lookup_field];
          if (
            conversionFields.includes(field_name) &&
            jsonResponse[lookup_field] != null
          ) {
            formatted_value = this.searchValueByKey(
              formatted_value,
              formatted_values,
            );
          }

          // if lookup_field has name with name_formatted_value then it will be used as formatted value
          if (jsonResponse.hasOwnProperty(lookup_field + '_formatted_value')) {
            formatted_value = jsonResponse[lookup_field + '_formatted_value'];
          }

          this.lineDataObj[this.rowKey]['columns'][field_name].formatted_value =
            formatted_value;
          this.$emit('inputValueChanges', field_name, this.rowKey);
        }
        this.resetMasterDataStore();
      } catch (err) {
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },

    resetChildFields(config: dynamicObj, triggerByField: string) {
      const lookup_fields = config.fields;
      for (let [index, field] of lookup_fields.entries()) {
        const field_name = field[this.attributeKey];

        if (
          triggerByField == field_name ||
          !this.lineDataObj[this.rowKey]['columns'][field_name]
        ) {
          continue;
        }
        this.lineDataObj[this.rowKey]['columns'][field_name].formatted_value =
          null;
        this.$emit('inputValueChanges', field_name, this.rowKey);
      }
    },

    setLookupFieldStatus(
      fields: any,
      enable: boolean,
      lookup_dataset_name: string,
      lookup_status: boolean | null,
    ) {
      for (let field of fields) {
        const field_name = field[this.attributeKey];

        if (
          !this.lineDataObj[this.rowKey]['columns'].hasOwnProperty(field_name)
        ) {
          continue;
        }

        if (
          !this.table_lookup_loading_fields.hasOwnProperty(field_name) ||
          !this.table_lookup_loading_fields[field_name].hasOwnProperty(
            this.rowKey,
          )
        ) {
          this.table_lookup_loading_fields[field_name] = {} as dynamicObj;
          this.table_lookup_loading_fields[field_name][this.rowKey] =
            {} as dynamicObj;
        }
        this.table_lookup_loading_fields[field_name][
          this.rowKey
        ].lookup_loading = enable;

        this.table_lookup_loading_fields[field_name][this.rowKey].lookup_found =
          lookup_status;
        this.table_lookup_loading_fields[field_name][
          this.rowKey
        ].lookup_found_name = lookup_dataset_name;
      }
    },
  },
  setup() {
    const lineItemStore = useLineItemStore();
    const { lineDataObj } = storeToRefs(lineItemStore);

    const lookup_function_store = useLookupFunctionStore();
    const { table_lookup_loading_fields } = storeToRefs(lookup_function_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const amount_format_store = useAmountFormatStore();
    const { formatMultiValues, searchValueByKey } = amount_format_store;

    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const { lookupTableDictionary, autoTriggerTableFields } = storeToRefs(
      doc_ms_data_lookup_store,
    );
    const {
      resetMasterDataStore,
      findDependentLookups,
      preapreAutoTriggerList,
      removeDuplicateGroups,
      loadAutoTriggerData,
    } = doc_ms_data_lookup_store;

    return {
      record,
      lineDataObj,
      lineItemStore,
      lookupTableDictionary,
      autoTriggerTableFields,
      table_lookup_loading_fields,
      searchValueByKey,
      formatMultiValues,
      findDependentLookups,
      resetMasterDataStore,
      loadAutoTriggerData,
      removeDuplicateGroups,
      preapreAutoTriggerList,
    };
  },
});
</script>
