<!--vbase-->
<template>
  <q-icon
    size="xs"
    draggable="true"
    class="draggable"
    @dragstart="handleDragStart($event, props)"
  >
    <Icon icon="mdi:drag" width="20" height="20" />
  </q-icon>

  <q-icon
    size="xs"
    class="q-ml-sm q-mr-sm cursor-pointer"
    draggable="false"
    @click.stop.prevent
  >
    <img
      class="icon-grey-svg"
      :src="getCostingElementIcon(lineDataObj[props.key])"
    />
    <q-menu
      @show="scrollToSelectedMenu(lineDataObj[props.key].costing_element)"
      auto-close
      transition-show="jump-down"
      transition-hide="jump-up"
      anchor="bottom middle"
      self="top middle"
      class="max-height-200"
    >
      <q-list dense style="min-width: 100px">
        <q-item
          clickable
          @click="onCostingElementSelect(line_item, props.key, props.rowIndex)"
        >
          <q-item-section avatar class="list-avatar">
            <q-icon name="undo" size="xs" class="icon-grey" />
          </q-item-section>
          <q-item-section>{{ $t('uncategorize') }}</q-item-section>
        </q-item>

        <q-separator />

        <template v-for="element of costingElementList" :key="element.value">
          <q-item
            clickable
            @click="
              onCostingElementSelect(element.value, props.key, props.rowIndex)
            "
            :id="costingElementIdPreFix + element.value"
            :class="
              lineDataObj[props.key].costing_element == element.value
                ? 'highlighted-back text-primary'
                : ''
            "
          >
            <q-item-section avatar class="list-avatar">
              <q-icon
                :name="'img:/images/charges/' + element.charge_icon"
                size="xs"
                class="icon-grey-svg"
              />
            </q-item-section>
            <q-item-section>{{ element.label }}</q-item-section>
          </q-item>
        </template>
      </q-list>
    </q-menu>
  </q-icon>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';

import helperUtil from 'src/utils/helperUtil';
import { type dynamicObj, $ } from 'src/pages/assets';
import { line_item, tableRowIdPreFix, CONSTANTS } from 'src/constants';
import { notify } from 'src/components/notifications/notify';
import {
  useDocumentStore,
  useLineItemStore,
  useMasterDataLookupStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperUtil],
  props: {
    props: {
      type: {} as any,
      required: true,
    },
  },
  
  data() {
    return {
      line_item: line_item,
      costingElementIdPreFix: CONSTANTS.costingElementIdPreFix,
    };
  },
  mounted: function () {
    this.init();

    // document.addEventListener('handle_row_sort', this.handleDrop);
  },
  // unmounted: function () {
  //   document.removeEventListener('handle_row_sort', this.handleDrop);
  // },

  methods: {
    async init() {
      try {
        this.costingElementList = await this.getCostingElementList(['1','3']);
      } catch (error) {
        logError('Failed to load costing elements:', error);
        this.costingElementList = [];
      }
    },
    onCostingElementSelect(
      costingElement: string,
      rowId: string,
      rowIndex: number,
    ) {
      // unset costingElement
      if (costingElement == this.line_item) {
        this.removeCostingElementsFromRow(rowId, rowIndex);

        // handle if next element  has parent id then update it
        const nextIndex = rowIndex + 1;
        if (
          this.record.tables[0].rows.length > nextIndex &&
          this.record.tables[0].rows[nextIndex].hasOwnProperty('parent_id')
        ) {
          const id = this.record.tables[0].rows[nextIndex].id;
          this.updateParentInRows(id, nextIndex, rowId);
        }
        return;
      }

      // update the table object and dictionary object
      this.lineDataObj[rowId].costing_element = costingElement;
      this.record.tables[0].rows[rowIndex].costing_element = costingElement;

      if (this.lineDataObj[rowId].parent_id) {
        return;
      }

      if (rowIndex == 0) {
        notify.error(this.$t('NO_PARENT_FOUND'));
        return;
      }

      // parent will be one step superior in index
      let rows = this.record.tables[0].rows;
      let parentId = '';
      let indexToUpdate = rowIndex - 1;

      parentId = rows[indexToUpdate].parent_id
        ? rows[indexToUpdate].parent_id
        : rows[indexToUpdate].id;
      this.updateParentInRows(rowId, rowIndex, parentId);

      // now check if current element was parent of some other elements then replace the parent id with new one
      for (let row of this.record.tables[0].rows) {
        if (row.parent_id && row.parent_id == rowId) {
          row.parent_id = parentId;
        }
      }
    },
    updateParentInRows(rowId: string, rowIndex: number, parentId: string) {
      let rows = this.record.tables[0].rows;
      rows[rowIndex].parent_id = parentId;
      this.lineDataObj[rowId].parent_id = parentId;
    },
    handleDragStart(event: any, props: any) {
      const row = props.row;
      const key = props.key;
      const rowIndex = props.rowIndex;

      const id: string = this.getRowIdPrefix() + key;

      event.dataTransfer.setData(
        'application/json',
        JSON.stringify({ rowIndex: rowIndex, rowId: props.key }),
      );
      // Get the parent element (in this case, the entire row) as the drag ghost
      const rowElement = document.querySelector('#' + id);

      if (!rowElement) {
        return;
      }
      // Clone the row element to avoid affecting the original structure
      const dragGhost = rowElement.cloneNode(true) as HTMLElement;

      // Adjust the ghost's styles to ensure it's visible during dragging
      dragGhost.style.position = 'absolute';
      // dragGhost.style.backgroundColor = 'white';
      // dragGhost.style.opacity = '1';
      // dragGhost.style.border = '1px solid gray';

      // Append to document body to create a custom drag image
      document.body.appendChild(dragGhost);

      // Set the custom drag image
      event.dataTransfer.setDragImage(dragGhost, 0, 0);

      // Clean up: Remove the ghost after setting it
      setTimeout(() => {
        document.body.removeChild(dragGhost);
      }, 0);
    },

    handleDrop(event: any, props: any) {
      // Prevent default behavior
      event.preventDefault();

      // Retrieve the data from the drag operation
      const data = event.dataTransfer.getData('application/json');
      if (!data) {
        return;
      }
      const droppedData = JSON.parse(data);

      // if dropped on same element do noting
      if (props.key == droppedData.rowId) {
        return;
      }

      this.removeCostingElementsFromRow(
        droppedData.rowId,
        droppedData.rowIndex,
      );

      let rowToMove = this.tableRows[droppedData.rowIndex];
      let itemToMove = this.record.tables[0].rows[droppedData.rowIndex];

      //remove the old item from old index
      this.tableRows.splice(droppedData.rowIndex, 1);
      this.record.tables[0].rows.splice(droppedData.rowIndex, 1);

      // update Table row object
      this.tableRows.splice(props.rowIndex, 0, rowToMove);

      // update Table main object
      this.record.tables[0].rows.splice(props.rowIndex, 0, itemToMove);

      // handle if next element  has parent id then update it
      const nextIndex = props.rowIndex + 1;
      if (
        this.record.tables[0].rows.length > nextIndex &&
        this.record.tables[0].rows[nextIndex].hasOwnProperty('parent_id')
      ) {
        const id = this.record.tables[0].rows[nextIndex].id;
        this.updateParentInRows(id, nextIndex, droppedData.rowIndex);
      }

      // on drag complete check if this element was parent of some other element then remove it
      for (let row of this.record.tables[0].rows) {
        if (row.parent_id && row.parent_id == droppedData.rowId) {
          delete row.parent_id;
          delete row.costing_element;
          this.removeCostingElementsFromDictionary(row.id);
        }
      }
    },
    // remove the costing form current element
    removeCostingElementsFromRow(rowId: string, rowIndex: number) {
      this.removeCostingElementsFromDictionary(rowId);
      this.removeCostingElementsFromStoreData(rowIndex);
    },
    removeCostingElementsFromDictionary(rowId: string) {
      delete this.lineDataObj[rowId].costing_element;
      delete this.lineDataObj[rowId].parent_id;
    },
    removeCostingElementsFromStoreData(rowIndex: number) {
      delete this.record.tables[0].rows[rowIndex].costing_element;
      delete this.record.tables[0].rows[rowIndex].parent_id;
    },
    scrollToSelectedMenu(costingElement: string) {
      let element = $(
        '#' + this.costingElementIdPreFix + costingElement,
      ) as HTMLElement;
      this.scrollInToViewStart(element);
    },
    getRowIdPrefix() {
      return tableRowIdPreFix;
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const doc_line_items_store = useLineItemStore();
    const { lineDataObj, tableRows } = storeToRefs(doc_line_items_store);

    const master_data_lookup = useMasterDataLookupStore();
    const {
      getCostingElementList,
      getCostingElementIcon,
    } = master_data_lookup;

    return {
      record,
      tableRows,
      lineDataObj,
      costingElementList: [] as any,

      getCostingElementList,
      getCostingElementIcon,
    };
  },
});
</script>

<style lang="scss" scoped></style>
